// __SLUG__-loop.js — generated by /atlas from this instance's topology.
//
// The multi-agent variant of `systemix loop`. It WRAPS the runner rather than
// reimplementing it — advancement goes through `systemix loop <id>` so there is
// exactly one card-writing code path (close-proposal cards dedupe in
// .systemix/queue.json). On top, it does what a single pass can't: audit each
// experiment surface through the ICP lens and queue ONE synthesis card.
//
// PROPOSE-ONLY: this workflow never closes an experiment and never edits
// skills or guardrails. Humans decide, via the queue.
//
// Do not hand-edit the topology below — it is baked from the `atlas:` block in
// systemix.config.yaml. To change it, run `/atlas update` and regenerate.
// Hermes may propose diffs to this file; those land as HITL cards.

export const meta = {
  name: '__SLUG__-loop',
  description: 'Topology-aware validation loop: advance running experiments to decision-ready, audit surfaces against the ICP, queue one synthesis card (propose-only).',
  phases: [
    { title: 'Recall', detail: 'running experiments + recent learnings' },
    { title: 'Advance', detail: 'systemix loop <id> per running experiment' },
    { title: 'Audit', detail: 'each surface through the ICP lens' },
    { title: 'Synthesize', detail: 'one HITL queue card' },
  ],
}

// ── Baked topology (source of truth: systemix.config.yaml `atlas:` block) ────
const TOPOLOGY = /*__ATLAS_TOPOLOGY__*/ {
  icp: 'REPLACED AT GENERATION',
  surfaces: [{ name: 'landing', path: 'src/app/page.tsx', conversionEvent: 'book_a_call' }],
  evidenceDays: 30,
  maxCandidates: 3,
}

const RECALL_SCHEMA = {
  type: 'object',
  required: ['experiments', 'learnings'],
  properties: {
    experiments: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id'],
        properties: { id: { type: 'string' }, section: { type: 'string' }, event: { type: 'string' } },
      },
    },
    learnings: { type: 'array', items: { type: 'string' }, description: 'recent LEARNINGS.md bullets, verbatim' },
  },
}

const ADVANCE_SCHEMA = {
  type: 'object',
  required: ['id', 'state'],
  properties: {
    id: { type: 'string' },
    state: { type: 'string', description: 'the runner\'s terminal state, e.g. decision-ready | waiting:insufficient-evidence | blocked:not-measured | blocked:not-wired | already-complete' },
    cardId: { type: 'string', description: 'close-proposal card id if one was queued or already pending' },
    note: { type: 'string', description: 'one line: leading variant + lift, or why blocked' },
  },
}

const AUDIT_SCHEMA = {
  type: 'object',
  required: ['surface', 'candidates'],
  properties: {
    surface: { type: 'string' },
    candidates: {
      type: 'array',
      items: {
        type: 'object',
        required: ['hypothesis', 'rationale'],
        properties: {
          hypothesis: { type: 'string', description: 'one falsifiable sentence, ICP-calibrated' },
          rationale: { type: 'string', description: 'why now — cite a learning or an observed weakness' },
        },
      },
    },
  },
}

const CARD_SCHEMA = {
  type: 'object',
  required: ['queued'],
  properties: { queued: { type: 'boolean' }, cardId: { type: 'string' }, reason: { type: 'string' } },
}

// ── Phase 1: recall ───────────────────────────────────────────────────────────
phase('Recall')
const state = await agent(
  `List this instance's RUNNING experiments and recall recent learnings.
   Experiments: run \`systemix experiment list\` (or MCP experiment_list) and keep
   only status=running; include each one's section and posthog-event if present.
   Learnings: run \`systemix experiment learnings --recent 5\` (or MCP
   experiment_learnings {recent:5}) and return the bullets verbatim.
   Read-only — change nothing.`,
  { label: 'recall', schema: RECALL_SCHEMA },
)

if (!state || (!state.experiments.length && !TOPOLOGY.surfaces.length)) {
  log('Nothing to do: no running experiments and no surfaces in the topology.')
  return { advanced: [], candidates: [], card: null }
}
log(`${state.experiments.length} running experiment(s), ${TOPOLOGY.surfaces.length} surface(s) to audit`)

// ── Phases 2+3: advance and audit — independent, run concurrently ────────────
// Advancement delegates to the runner: one card path, dedupe intact.
const advancePromise = pipeline(
  state.experiments,
  (e) =>
    agent(
      `Run \`systemix loop ${e.id} --days ${TOPOLOGY.evidenceDays}\` and report the
       outcome. Do NOT close the experiment, edit its file, or write any card
       yourself — the runner owns all writes. Report the terminal state the
       runner printed, the close-proposal card id if it queued (or found) one,
       and a one-line note (leading variant + lift, or why blocked).`,
      { label: `loop:${e.id}`, phase: 'Advance', schema: ADVANCE_SCHEMA },
    ),
)

// The ICP lens: propose candidate NEXT experiments per surface — as data only.
const auditPromise = Promise.all(
  TOPOLOGY.surfaces.map((s) =>
    agent(
      `Audit the "${s.name}" surface (source: ${s.path}, conversion event:
       "${s.conversionEvent}") through the ICP lens.
       ICP: ${TOPOLOGY.icp}
       Recent learnings (do not re-propose what is already learned):
       ${state.learnings.map((l) => `- ${l}`).join('\n')}
       Read the surface source and propose at most ${TOPOLOGY.maxCandidates}
       candidate experiments: falsifiable hypotheses calibrated to this ICP,
       each with a one-line rationale citing a learning or an observed weakness.
       Read-only — write no files, create no experiments.`,
      { label: `audit:${s.name}`, phase: 'Audit', schema: AUDIT_SCHEMA },
    ),
  ),
)

const [advanced, audits] = await Promise.all([advancePromise, auditPromise])
const results = advanced.filter(Boolean)
const candidates = audits.filter(Boolean).flatMap((a) => a.candidates.map((c) => ({ surface: a.surface, ...c })))

// ── Phase 4: synthesize — one card, not one per finding ──────────────────────
// Barrier is correct here: the card needs ALL advance outcomes and candidates.
phase('Synthesize')
const decisionReady = results.filter((r) => r.state === 'decision-ready')
const card = await agent(
  `Queue ONE synthesis card in the Systemix HITL queue via MCP push_hitl_task
   (load it via ToolSearch if deferred). Shape:
   { "type": "synthesis",
     "hypothesis": "__SLUG__ loop run: ${decisionReady.length} decision-ready of ${results.length} running",
     "context": <compact summary of the runner outcomes below + top candidates>,
     "recommendation": <the single highest-leverage next action>,
     "confidence": <0..1, your calibration>,
     "component": "loop" }
   Runner outcomes: ${JSON.stringify(results)}
   Candidates: ${JSON.stringify(candidates)}
   Recommend closing via /close-experiment for decision-ready ids; recommend
   /init-experiment for at most the single best candidate. Queue exactly one
   card. If the Systemix MCP is unavailable, queue nothing and say so in
   "reason" — do not write .systemix/queue.json directly.`,
  { label: 'synthesis-card', schema: CARD_SCHEMA },
)

return {
  advanced: results,
  candidates,
  card,
  next: decisionReady.length
    ? `review the queue, then /close-experiment ${decisionReady.map((r) => r.id).join(', ')}`
    : 'no experiment is decision-ready; review the synthesis card for candidates',
}
